def count_paths(H: int, W: int, K: int, grid: list[str]) -> int:
    """Count paths of K orthogonal moves through distinct empty cells.

    Each empty cell may be a starting point. Paths with opposite traversal
    directions are counted separately.
    """
    cells = [(r, c) for r in range(H) for c in range(W) if grid[r][c] == "."]
    if len(cells) <= K:
        return 0

    indices = {cell: i for i, cell in enumerate(cells)}
    neighbors = [[] for _ in cells]
    for i, (r, c) in enumerate(cells):
        for dr, dc in ((-1, 0), (1, 0), (0, -1), (0, 1)):
            j = indices.get((r + dr, c + dc))
            if j is not None:
                neighbors[i].append(j)

    visited = [False] * len(cells)

    def search(cell: int, remaining: int) -> int:
        if remaining == 0:
            return 1
        total = 0
        for nxt in neighbors[cell]:
            if not visited[nxt]:
                visited[nxt] = True
                total += search(nxt, remaining - 1)
                visited[nxt] = False
        return total

    total = 0
    for start in range(len(cells)):
        visited[start] = True
        total += search(start, K)
        visited[start] = False
    return total

from typing import List, Tuple


def min_sensor_cost(n: int, sections: List[int], sensor1: Tuple[int, int, int], sensor2: Tuple[int, int, int]) -> int:
    """Return the minimum cost of covering every section, or -1 if impossible.

    Each sensor is assigned to one section. Coverage may overlap or exceed a
    section's length, and the two sensor counts are bounded globally.
    """
    l1, c1, k1 = sensor1
    l2, c2, k2 = sensor2
    # Either type alone never needs more than this many sensors.
    k1 = min(k1, sum((d + l1 - 1) // l1 for d in sections))
    k2 = min(k2, sum((d + l2 - 1) // l2 for d in sections))
    if k1 > k2:
        l1, c1, k1, l2, c2, k2 = l2, c2, k2, l1, c1, k1

    # Frontier entries are (type 1 count, minimum type 2 count).
    # Entries using at least as many of both types are dominated.
    frontier = [(0, 0)]
    for d in sections:
        options = []
        previous_b = k2 + 1
        first_a = max(0, (d - k2 * l2 + l1 - 1) // l1)
        last_a = min(k1, (d + l1 - 1) // l1)
        for a in range(first_a, last_a + 1):
            b = max(0, (d - a * l1 + l2 - 1) // l2)
            if b < previous_b:
                options.append((a, b))
                previous_b = b
        if not options:
            return -1

        best = [k2 + 1] * (k1 + 1)
        for used_a, used_b in frontier:
            for a, b in options:
                total_a = used_a + a
                if total_a > k1:
                    break
                total_b = used_b + b
                if total_b < best[total_a]:
                    best[total_a] = total_b

        frontier = []
        minimum_b = k2 + 1
        for a, b in enumerate(best):
            if b < minimum_b:
                frontier.append((a, b))
                minimum_b = b
        if not frontier:
            return -1

    return min(a * c1 + b * c2 for a, b in frontier)

def can_transform(k: int, s: str, t: str) -> bool:
    """Determine if s can be transformed into t with at most k edits.

    An edit inserts, deletes, or replaces one character.
    Strings may contain up to 500000 characters; k is at most 20.
    """
    n, m = len(s), len(t)
    if abs(n - m) > k:
        return False

    # On diagonal d, a source position x corresponds to target position x-d.
    # Keep only the farthest position reachable with each edit budget.
    x = 0
    while x < n and x < m and s[x] == t[x]:
        x += 1
    if x == n and x == m:
        return True
    previous = {0: x}

    for edits in range(1, k + 1):
        current = {}
        for diagonal in range(max(-edits, -m), min(edits, n) + 1):
            farthest = -1

            # Delete from the source: the diagonal increases by one.
            pos = previous.get(diagonal - 1, -1)
            if 0 <= pos < n:
                farthest = pos + 1

            # Insert into the source: the diagonal decreases by one.
            pos = previous.get(diagonal + 1, -1)
            if pos >= 0 and pos - (diagonal + 1) < m:
                farthest = max(farthest, pos)

            # Replace a character: the diagonal stays the same.
            pos = previous.get(diagonal, -1)
            if 0 <= pos < n and pos - diagonal < m:
                farthest = max(farthest, pos + 1)

            if farthest < 0:
                continue
            target_pos = farthest - diagonal
            while farthest < n and target_pos < m and s[farthest] == t[target_pos]:
                farthest += 1
                target_pos += 1
            if farthest == n and target_pos == m:
                return True
            current[diagonal] = farthest
        previous = current
    return False

from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length, digit_sum, needed):
    """Count nonzero-digit suffixes with this sum and required product factor."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and needed == 1)
    return sum(
        _suffix_count(length - 1, digit_sum - digit, needed // gcd(needed, digit))
        for digit in range(1, 10)
    )


def _smooth(value):
    for prime in (2, 3, 5, 7):
        while value % prime == 0:
            value //= prime
    return value == 1


_SUMS = tuple(value for value in range(1, 82) if _smooth(value))


@lru_cache(maxsize=None)
def _beautiful_length(length):
    return sum(_suffix_count(length, total, total)
               for total in _SUMS if total <= 9 * length)


def _count_up_to(bound):
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    length = len(digits)

    # Every positive number containing a zero has product zero.
    without_zero = sum(9 ** size for size in range(1, length))
    for index, digit in enumerate(digits):
        if digit == 0:
            break
        without_zero += (digit - 1) * 9 ** (length - index - 1)
    else:
        without_zero += 1
    result = bound - without_zero

    result += sum(_beautiful_length(size) for size in range(1, length))
    prefix_sum = 0
    prefix_product = 1
    for index, digit in enumerate(digits):
        remaining = length - index - 1
        for smaller in range(1, digit):
            current_sum = prefix_sum + smaller
            current_product = prefix_product * smaller
            for total in _SUMS:
                suffix_sum = total - current_sum
                if remaining <= suffix_sum <= 9 * remaining:
                    result += _suffix_count(
                        remaining, suffix_sum, total // gcd(total, current_product)
                    )
        if digit == 0:
            break
        prefix_sum += digit
        prefix_product *= digit
    else:
        result += int(prefix_product % prefix_sum == 0)
    return result


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

