from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length, digit_sum, needed):
    """Count nonzero-digit suffixes with this sum and required product factor."""
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    if length == 0:
        return int(digit_sum == 0 and needed == 1)
    return sum(
        _suffix_count(length - 1, digit_sum - digit, needed // gcd(needed, digit))
        for digit in range(1, 10)
    )


def _smooth(value):
    for prime in (2, 3, 5, 7):
        while value % prime == 0:
            value //= prime
    return value == 1


_SUMS = tuple(value for value in range(1, 82) if _smooth(value))


@lru_cache(maxsize=None)
def _beautiful_length(length):
    return sum(_suffix_count(length, total, total)
               for total in _SUMS if total <= 9 * length)


def _count_up_to(bound):
    if bound <= 0:
        return 0
    digits = tuple(map(int, str(bound)))
    length = len(digits)

    # Every positive number containing a zero has product zero.
    without_zero = sum(9 ** size for size in range(1, length))
    for index, digit in enumerate(digits):
        if digit == 0:
            break
        without_zero += (digit - 1) * 9 ** (length - index - 1)
    else:
        without_zero += 1
    result = bound - without_zero

    result += sum(_beautiful_length(size) for size in range(1, length))
    prefix_sum = 0
    prefix_product = 1
    for index, digit in enumerate(digits):
        remaining = length - index - 1
        for smaller in range(1, digit):
            current_sum = prefix_sum + smaller
            current_product = prefix_product * smaller
            for total in _SUMS:
                suffix_sum = total - current_sum
                if remaining <= suffix_sum <= 9 * remaining:
                    result += _suffix_count(
                        remaining, suffix_sum, total // gcd(total, current_product)
                    )
        if digit == 0:
            break
        prefix_sum += digit
        prefix_product *= digit
    else:
        result += int(prefix_product % prefix_sum == 0)
    return result


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

